    expect(only([route]).closingEdge).toBeNull();
  });

  it("draws the closing edge when it does", () => {
    const looped = obstacle({ ...(route.motion as never), loop: true, ping_pong: false });
    expect(only([looped]).closingEdge).toEqual([
      { x: 5, y: 6 },
      { x: 1, y: 1 },
